use super::*;
pub struct FabricTriangle {pub ids:[usize;3],u:[f64;3],v:[f64;3],lambda:[f64;3]}
impl FabricTriangle {
 pub fn new(ids:[usize;3],uv:&[[f64;2]])->Result<Self,String>{let a=uv[ids[0]];let b=uv[ids[1]];let c=uv[ids[2]];let x=b[0]-a[0];let y=b[1]-a[1];let z=c[0]-a[0];let t=c[1]-a[1];let det=x*t-z*y;if det.abs()<1e-14{return Err("Degenerate fabric coordinates".into())}let u=[(y-t)/det,t/det,-y/det];let v=[(z-x)/det,-z/det,x/det];Ok(Self{ids,u,v,lambda:[0.;3]})}
 pub fn reset(&mut self){self.lambda=[0.;3];}
 pub fn sample(&self,p:&[V])->([f64;3],[[V;3];3]){let u=(0..3).fold([0.;3],|a,i|add(a,mul(p[self.ids[i]],self.u[i])));let v=(0..3).fold([0.;3],|a,i|add(a,mul(p[self.ids[i]],self.v[i])));let lu=norm(u);let lv=norm(v);let strains=[lu-1.,lv-1.,dot(u,v)];let gradients=std::array::from_fn(|mode|std::array::from_fn(|i|match mode{0=>mul(u,self.u[i]/lu.max(1e-12)),1=>mul(v,self.v[i]/lv.max(1e-12)),_=>add(mul(v,self.u[i]),mul(u,self.v[i]))}));(strains,gradients)}
 pub fn add_forces(&self,p:&[V],area:f64,stiffness:[f64;3],forces:&mut[V])->f64{let(e,g)=self.sample(p);for mode in 0..3{for i in 0..3{forces[self.ids[i]]=sub(forces[self.ids[i]],mul(g[mode][i],area*stiffness[mode]*e[mode]));}}0.5*area*(0..3).map(|i|stiffness[i]*e[i]*e[i]).sum::<f64>()}
 pub fn solve(&mut self,p:&mut[V],w:&[f64],compliance:[f64;3],dt:f64){for mode in 0..3{let u=(0..3).fold([0.;3],|a,i|add(a,mul(p[self.ids[i]],self.u[i])));let v=(0..3).fold([0.;3],|a,i|add(a,mul(p[self.ids[i]],self.v[i])));let len=norm(if mode==0{u}else{v});if mode<2&&len<1e-10{continue}let value=if mode==2{dot(u,v)}else{len-1.};let gradients:[V;3]=std::array::from_fn(|i|match mode{0=>mul(u,self.u[i]/len),1=>mul(v,self.v[i]/len),_=>add(mul(v,self.u[i]),mul(u,self.v[i]))});let alpha=compliance[mode]/(dt*dt);let mass=(0..3).map(|i|w[self.ids[i]]*dot(gradients[i],gradients[i])).sum::<f64>();if mass==0.{continue}let dl=(-value-alpha*self.lambda[mode])/(mass+alpha);self.lambda[mode]+=dl;for i in 0..3{p[self.ids[i]]=add(p[self.ids[i]],mul(gradients[i],w[self.ids[i]]*dl));}}}
}
